import { GoogleGenAI, Type } from "@google/genai";

export async function generateMarketingContent(prompt: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    Você é o Agente Greatek de Marketing IA. Especialista em B2B Telecom (ISPs).
    Seu objetivo é gerar pautas, roteiros de Reels e hooks de Instagram que transformem conhecimento técnico em autoridade e leads.
    Foco: Redução de OPEX, Estabilidade, Energia Crítica, Wi-Fi 7, SDN, L7.
    Tom de voz: Profissional, autoritário, direto ao ponto e focado em lucro/estabilidade do ISP.
    Regra-mãe: Criar critério de decisão no seguidor, não apenas vender produto.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction,
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING, description: "Gancho inicial de 3 segundos para Reels" },
            body: { type: Type.ARRAY, items: { type: Type.STRING }, description: "3-5 pontos chave do conteúdo" },
            cta: { type: Type.STRING, description: "Chamada para ação focada em DM ou Comentário" },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Palavras-chave para SEO" }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Error generating content:", error);
    return { error: "Falha ao gerar conteúdo. Verifique sua conexão." };
  }
}

