import React, { useState } from 'react';
import { generateMarketingContent } from '../services/geminiService';

const Assistant: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setResult(null);

    const prompt = `Gere uma pauta completa sobre o tema: "${topic}". Foque em como isso ajuda o dono de ISP a lucrar mais ou ter menos dor de cabeça técnica.`;
    const data = await generateMarketingContent(prompt);
    setResult(data);
    setLoading(false);
  };

  return (
    <div id="assistant" className="scroll-mt-6">
      <div className="bg-slate-900/40 border border-blue-500/20 rounded-[2rem] p-8 shadow-2xl overflow-hidden relative">
        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
          <svg className="w-32 h-32 text-blue-500" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 2L4.5 20.29L5.21 21L12 18L18.79 21L19.5 20.29L12 2Z" />
          </svg>
        </div>

        <h2 className="text-2xl font-extrabold mb-2 bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">
          Greatek AI Assistant
        </h2>
        <p className="text-slate-400 text-sm mb-6 max-w-xl">
          Transforme temas técnicos em posts virais e estratégicos em segundos. Otimizado para equipes de 2 pessoas.
        </p>

        <div className="flex flex-col md:flex-row gap-3 mb-8">
          <input 
            type="text" 
            placeholder="Ex: Wi-Fi 7 no ISP ou Redução de OPEX com energia solar..."
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            className="flex-1 bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 outline-none focus:border-blue-500 transition-all text-sm"
          />
          <button 
            onClick={handleGenerate}
            disabled={loading}
            className="bg-blue-600 hover:bg-blue-500 disabled:bg-blue-800 text-white font-bold py-3 px-8 rounded-xl transition-all shadow-lg shadow-blue-500/20 flex items-center justify-center gap-2"
          >
            {loading ? (
              <>
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                Gerando...
              </>
            ) : 'Gerar Pauta'}
          </button>
        </div>

        {result && !result.error && (
          <div className="bg-slate-950/50 border border-slate-800 rounded-2xl p-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-start justify-between mb-4">
              <h3 className="font-bold text-lg text-blue-400">{result.title}</h3>
              <span className="text-[10px] bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-2 py-1 rounded-full font-bold uppercase">Prompt Gemini OK</span>
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-1">Gancho (3 Segundos)</label>
                  <div className="bg-white/5 p-3 rounded-lg border border-white/10 text-sm font-medium italic">"{result.hook}"</div>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-1">Pontos Chave</label>
                  <ul className="space-y-2">
                    {result.body.map((item: string, i: number) => (
                      <li key={i} className="text-sm text-slate-300 flex gap-2">
                        <span className="text-blue-500 font-bold">•</span> {item}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-1">CTA (Call to Action)</label>
                  <div className="bg-blue-500/10 p-3 rounded-lg border border-blue-500/20 text-sm text-blue-200">{result.cta}</div>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-1">SEO Tags</label>
                  <div className="flex flex-wrap gap-2">
                    {result.keywords.map((tag: string, i: number) => (
                      <span key={i} className="text-[11px] bg-slate-800 px-2 py-1 rounded-md text-slate-400">#{tag.replace(/\s+/g, '')}</span>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {result?.error && (
          <div className="p-4 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-sm font-medium">
            {result.error}
          </div>
        )}
      </div>
    </div>
  );
};

