import { GoogleGenAI, Type } from "@google/genai";

export async function generateMarketingContent(prompt: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    Você é o Agente Greatek de Marketing IA. Especialista em Estratégia B2B para Telecom (ISPs).
    Seu objetivo é gerar conteúdo para Instagram (Reels/Stories), Blog (Artigos SEO) e E-mail Marketing (RD Station).
    O foco deve ser: Redução de OPEX, Estabilidade de Rede, Energia Crítica, Wi-Fi 7, SDN e Gestão de Provedores.
    Tom de voz: Técnico porém acessível, autoritário, focado em retorno sobre investimento (ROI) para o ISP.
    Regra-mãe: Educar o mercado para criar critérios de decisão que favoreçam a qualidade da Greatek.
    Você ajuda uma equipe enxuta de 2 pessoas a ter escala de multinacional.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction,
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Título chamativo para o post ou artigo" },
            hook: { type: Type.STRING, description: "Gancho inicial ou Assunto do E-mail" },
            body: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Estrutura do conteúdo (pontos chave)" },
            cta: { type: Type.STRING, description: "Chamada para ação estratégica (DM, Link Blog ou RD)" },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Tags SEO e Hashtags" }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Error generating content:", error);
    return { error: "Falha ao gerar conteúdo. Verifique sua conexão." };
  }
}

import React, { useState, useEffect, useMemo } from 'react';
import { XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import Sidebar from './components/Sidebar';
import Assistant from './components/Assistant';
import { WEEKLY_TASKS, PILLARS, QUARTERS, CHART_DATA, MOTIVATIONAL_QUOTES } from './constants';
import { Task } from './types';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('visao');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [modal, setModal] = useState<{ id: string; open: boolean }>({ id: '', open: false });
  const [notes, setNotes] = useState({ week: '', month: '' });
  const [currentQuoteIndex, setCurrentQuoteIndex] = useState(0);

  // Quote rotation logic
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentQuoteIndex(prev => (prev + 1) % MOTIVATIONAL_QUOTES.length);
    }, 8000);
    return () => clearInterval(interval);
  }, []);

  // Persistence logic
  useEffect(() => {
    const savedTasks = localStorage.getItem('greatek_tasks_2026');
    const savedNotes = localStorage.getItem('greatek_notes_2026');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    else setTasks(WEEKLY_TASKS);

    if (savedNotes) setNotes(JSON.parse(savedNotes));
  }, []);

  useEffect(() => {
    if (tasks.length > 0) localStorage.setItem('greatek_tasks_2026', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('greatek_notes_2026', JSON.stringify(notes));
  }, [notes]);

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const progress = useMemo(() => {
    const done = tasks.filter(t => t.completed).length;
    return Math.round((done / tasks.length) * 100) || 0;
  }, [tasks]);

  const resetAll = () => {
    if (confirm('Deseja resetar todo o progresso e notas do Planejamento 2026?')) {
      setTasks(WEEKLY_TASKS);
      setNotes({ week: '', month: '' });
      localStorage.removeItem('greatek_tasks_2026');
      localStorage.removeItem('greatek_notes_2026');
      alert('Reset realizado.');
    }
  };

  const ModalContent = ({ id }: { id: string }) => {
    const titles: Record<string, string> = {
      'modal-exec': 'Protocolo de Execução Ágil',
      'modal-dm': 'Script Funil Y & Atendimento RD',
