      'modal-conteudo': 'Multicanalidade: Blog + Insta + Email',
      'modal-posicionamento': 'Inteligência e Qualificação de Leads',
      'modal-distribuicao': 'Estratégia RD Station & Tráfego',
      'modal-engajamento': 'Thought Leadership Telecom',
      'modal-q1': 'Detalhamento Estratégico Q1',
    };

    return (
      <div className="p-6 text-slate-300 space-y-4">
        <h3 className="text-xl font-bold text-white mb-4">{titles[id] || 'Orientações'}</h3>
        <p className="text-sm leading-relaxed">
          Para sustentar esse ecossistema com apenas 2 pessoas, a palavra-chave é <strong>Reciclagem de Conteúdo</strong>.
        </p>
        <div className="space-y-3">
          <div className="bg-slate-800/50 p-3 rounded-lg border border-slate-700">
            <span className="text-blue-400 font-bold block text-xs mb-1">Passo 1: Blog Primeiro</span>
            <p className="text-[11px]">Escreva um artigo técnico denso no Blog. Ele é a sua base de autoridade e SEO.</p>
