import React, { useState, useEffect, useMemo } from 'react';
import { XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import Sidebar from './components/Sidebar';
import Assistant from './components/Assistant';
import { WEEKLY_TASKS, PILLARS, QUARTERS, CHART_DATA, MOTIVATIONAL_QUOTES, SWOT, CONTINGENCY_PLANS } from './constants';
import { Task } from './types';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('visao');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [modal, setModal] = useState<{ id: string; open: boolean }>({ id: '', open: false });
  const [notes, setNotes] = useState({ week: '', month: '' });
  const [currentQuoteIndex, setCurrentQuoteIndex] = useState(0);
  const [saveStatus, setSaveStatus] = useState<'salvo' | 'editando'>('salvo');

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentQuoteIndex(prev => (prev + 1) % MOTIVATIONAL_QUOTES.length);
    }, 8000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const savedTasks = localStorage.getItem('greatek_tasks_2026_v5');
    const savedNotes = localStorage.getItem('greatek_notes_2026_v5');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    else setTasks(WEEKLY_TASKS);
    if (savedNotes) setNotes(JSON.parse(savedNotes));
  }, []);

  useEffect(() => {
    if (tasks.length > 0) localStorage.setItem('greatek_tasks_2026_v5', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('greatek_notes_2026_v5', JSON.stringify(notes));
    setSaveStatus('salvo');
  }, [notes]);

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const progress = useMemo(() => {
    const done = tasks.filter(t => t.completed).length;
    return Math.round((done / tasks.length) * 100) || 0;
  }, [tasks]);

  const handleExportPlan = () => {
    const content = `PLANILHA DE EXECUÇÃO GREATEK 2026\nStatus: ${progress}% Concluído\n\nTarefas:\n${tasks.map(t => `[${t.completed ? 'X' : ' '}] ${t.title}: ${t.desc}`).join('\n')}\n\nFoco Estratégico: Terça é dia de batching audiovisual.`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `plano_sprint_greatek_${new Date().toLocaleDateString()}.txt`;
    link.click();
  };

  const handleExportJournal = () => {
    const content = `INSIGHT JOURNAL - GREATEK 2026\nData: ${new Date().toLocaleDateString()}\n\nOPERACIONAL:\n${notes.week}\n\nESTRATÉGICO:\n${notes.month}`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `insights_greatek_${new Date().toLocaleDateString()}.txt`;
    link.click();
  };

  const ModalContent = ({ id }: { id: string }) => {
    const getModalData = () => {
      switch (id) {
        case 'modal-conteudo':
          return {
            title: "Estratégia de Conteúdo",
            subtitle: "Educar para Criar Critério de Decisão",
            body: [
              { label: "Reels (Atração)", text: "Vídeos de 30-60s focados em quebra de padrão e alertas de erros técnicos que custam dinheiro ao ISP." },
              { label: "Carrosséis (Autoridade)", text: "Frameworks profundos de 6 a 10 slides. Comparativos de arquitetura e guias de decisão técnica." },
              { label: "Stories (Conversão)", text: "Bastidores, enquetes de decisão e CTA direto para o Agente Greatek ou DM consultiva." }
            ],
            tip: "O conteúdo não deve vender o produto, mas sim o motivo pelo qual o ISP precisa de uma solução robusta."
          };
        case 'modal-posicionamento':
          return {
            title: "Posicionamento B2B",
            subtitle: "Hub de Inteligência Telecom",
            body: [
              { label: "Diferenciação", text: "Saímos do papel de 'vendedor de caixa' para 'orientador estratégico'. Focamos em impacto financeiro e OPEX." },
              { label: "Território Único", text: "A Greatek ocupa o espaço da inteligência por trás das decisões técnicas complexas." },
              { label: "Voz de Autoridade", text: "Linguagem direta para o dono do ISP: Engenharia + Negócio." }
            ],
            tip: "Seu diferencial não é o que você vende, mas sim como você ensina o mercado a pensar."
          };
        case 'modal-distribuicao':
          return {
            title: "Canais & Distribuição",
            subtitle: "Furar a Bolha e SEO Ativo",
            body: [
              { label: "SEO Instagram", text: "Palavras-chave estratégicas (Wi-Fi 7, XGS-PON, Energia Crítica) em Bio, nomes e legendas." },
              { label: "Hashtags Reais", text: "Foco em micro-nicho: #ispbr, #engenhariaderedes. Fuja de tags de vaidade com milhões de posts." },
              { label: "Colaborações", text: "Reels em conjunto com engenheiros e consultores respeitados no nicho de Telecom." }
            ],
            tip: "O algoritmo não distribui marcas institucionais, ele distribui comportamentos humanos e soluções úteis."
          };
        case 'modal-engajamento':
          return {
            title: "Engajamento & CRM",
            subtitle: "Conversa vale mais que Curtida",
