import React, { useState } from 'react';
import { generateMarketingContent } from '../services/geminiService';

const Assistant: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setResult(null);
    setCopied(false);

    const prompt = `Gere um planejamento tático multicanal completo para o tema: "${topic}". Explique como usar em Instagram, Blog e RD Station.`;
    const data = await generateMarketingContent(prompt);
    setResult(data);
    setLoading(false);
  };

  const copyToClipboard = () => {
    if (!result) return;
    const text = `ESTRATÉGIA GREATEK: ${result.title}\n\nGANCHO: ${result.hook}\n\nCONTEÚDO:\n${result.body.join('\n')}\n\nCTA: ${result.cta}\n\nKEYWORDS: ${result.keywords.join(', ')}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div id="assistant" className="scroll-mt-24 mb-32">
      <div className="bg-slate-900/40 border border-slate-800 rounded-[3rem] p-10 md:p-14 shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600/5 blur-[120px] rounded-full pointer-events-none"></div>

        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-10 mb-16 relative z-10">
          <div className="max-w-xl">
            <div className="inline-flex items-center gap-2 px-3 py-1 bg-blue-500/10 border border-blue-500/20 rounded-full text-blue-400 text-[9px] font-black uppercase tracking-widest mb-4">
