import React, { useState } from 'react';
import { generateMarketingContent } from '../services/geminiService';

const Assistant: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setResult(null);
    setCopied(false);

    const prompt = `Gere um planejamento tático multicanal completo para o tema: "${topic}". Explique como usar em Instagram, Blog e RD Station.`;
    const data = await generateMarketingContent(prompt);
    setResult(data);
    setLoading(false);
  };

  const copyToClipboard = () => {
    if (!result) return;
    const text = `ESTRATÉGIA GREATEK: ${result.title}\n\nGANCHO: ${result.hook}\n\nCONTEÚDO:\n${result.body.join('\n')}\n\nCTA: ${result.cta}\n\nKEYWORDS: ${result.keywords.join(', ')}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div id="assistant" className="scroll-mt-24 mb-32">
      <div className="bg-slate-900/40 border border-slate-800 rounded-[4rem] p-12 md:p-16 shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-600/5 blur-[150px] rounded-full pointer-events-none group-hover:bg-blue-600/10 transition-all duration-1000"></div>

        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-12 mb-16 relative z-10">
          <div className="max-w-2xl">
            <div className="inline-flex items-center gap-3 px-4 py-2 bg-blue-500/10 border border-blue-500/20 rounded-full text-blue-400 text-[10px] font-black uppercase tracking-[0.2em] mb-6">
              <span className="w-2 h-2 bg-blue-400 rounded-full animate-pulse"></span>
              Greatek AI Command (Team scale x10)
            </div>
            <h2 className="text-5xl font-black text-white tracking-tighter mb-6 leading-tight">Greatek Assistant</h2>
            <p className="text-slate-400 text-lg font-medium leading-relaxed mb-8">
              Transforme tendências técnicas em pautas multicanal de alto impacto. 
              Digite um tema e receba a estrutura completa para Reels, Blog e E-mail.
            </p>

            <div className="bg-slate-950/50 p-6 rounded-3xl border border-slate-800 flex gap-6 items-start">
               <div className="w-10 h-10 bg-blue-600/20 rounded-xl flex items-center justify-center text-blue-400 font-bold shrink-0">?</div>
               <div>
                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-1">Como utilizar:</span>
                  <p className="text-xs text-slate-400 font-bold leading-relaxed">
                    1. Insira o tema (ex: Wi-Fi 7). 2. A IA gera a pauta estratégica. 
                    3. Copie e cole no roteiro do Reels (Terça) e no RD Station (Quarta).
                  </p>
               </div>
            </div>
          </div>

          <div className="flex flex-col gap-4 w-full lg:w-[450px]">
            <input 
              type="text" 
              placeholder="Ex: Por que ISPs precisam de Wi-Fi 7?"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              className="bg-slate-950 border border-slate-800 rounded-3xl px-8 py-6 outline-none focus:border-blue-500 transition-all text-lg text-white w-full shadow-inner placeholder:text-slate-800 font-medium"
            />
            <button 
              onClick={handleGenerate}
              disabled={topic.length < 3 || loading}
              className="bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 text-white font-black py-6 rounded-3xl transition-all shadow-2xl flex items-center justify-center gap-4 text-lg active:scale-95 group/btn"
            >
              {loading ? (
                <div className="w-6 h-6 border-3 border-white/20 border-t-white rounded-full animate-spin"></div>
              ) : (
                <>
                  <span>Planejar Campanha</span>
                  <svg className="w-5 h-5 group-hover/btn:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                </>
              )}
            </button>
          </div>
        </div>

