import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const BASE_SYSTEM_INSTRUCTION = `
    Você é o Agente Greatek de Marketing IA. Especialista em Estratégia B2B para Telecom (ISPs).
    Seu objetivo é gerar conteúdo para Instagram (Reels/Stories), Blog (Artigos SEO) e E-mail Marketing (RD Station).
    O foco deve ser: Redução de OPEX, Estabilidade de Rede, Energia Crítica, Wi-Fi 7, SDN e Gestão de Provedores.
    Tom de voz: Técnico porém acessível, autoritário, focado em retorno sobre investimento (ROI) para o ISP.
    Regra-mãe: Educar o mercado para criar critérios de decisão que favoreçam a qualidade da Greatek.
    Você ajuda uma equipe enxuta de 2 pessoas a ter escala de multinacional.
`;

export async function generateMarketingContent(prompt: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Título chamativo para o post ou artigo" },
            hook: { type: Type.STRING, description: "Gancho inicial ou Assunto do E-mail" },
            body: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Estrutura do conteúdo (pontos chave)" },
            cta: { type: Type.STRING, description: "Chamada para ação estratégica (DM, Link Blog ou RD)" },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Tags SEO e Hashtags" }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Error generating content:", error);
    return { error: "Falha ao gerar conteúdo." };
  }
}

export async function mirrorContent(reference: string) {
  const prompt = `
    Analise a seguinte referência de conteúdo de telecom/tecnologia e faça o "ESPELHAMENTO" para a marca Greatek:
    REFERÊNCIA: "${reference}"

    TAREFAS:
    1. Identifique o gatilho psicológico/técnico que faz esse conteúdo funcionar.
    2. Crie um roteiro de Reels (30-60s) adaptado para o portfólio Greatek.
    3. Substitua termos genéricos por "tecniquês" de campo do ISP brasileiro (ONU, CTO, Sangria, Fusão, Surto, etc).
    4. Insira uma solução específica da Greatek (Energia, Rede ou Wi-Fi) como a solução do problema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.8,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING, description: "Por que o original funciona" },
            mirroredScript: { type: Type.STRING, description: "Roteiro Greatek completo" },
            technicalEdge: { type: Type.STRING, description: "Qual produto Greatek usar e por que" },
            cta: { type: Type.STRING, description: "CTA focado em conversão técnica" }
          },
          required: ["analysis", "mirroredScript", "technicalEdge", "cta"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Error mirroring content:", error);
    return { error: "Falha ao espelhar conteúdo." };
  }
}

