const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('visao');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [modal, setModal] = useState<{ id: string; open: boolean }>({ id: '', open: false });

  useEffect(() => {
    const savedTasks = localStorage.getItem('greatek_tasks_2026_v10');
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    else setTasks(WEEKLY_TASKS);
  }, []);

  useEffect(() => {
    if (tasks.length > 0) localStorage.setItem('greatek_tasks_2026_v10', JSON.stringify(tasks));
  }, [tasks]);

  const [currentQuoteIndex, setCurrentQuoteIndex] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentQuoteIndex(prev => (prev + 1) % MOTIVATIONAL_QUOTES.length);
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const progress = useMemo(() => {
    const done = tasks.filter(t => t.completed).length;
    return Math.round((done / tasks.length) * 100) || 0;
  }, [tasks]);

  const handleExportPlan = () => {
    const content = `SPRINT GREATEK 2026\nProgresso: ${progress}%\n\nTarefas:\n${tasks.map(t => `[${t.completed ? 'X' : ' '}] ${t.title}`).join('\n')}`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `sprint_greatek.txt`;
    link.click();
  };

  const ModalContent = ({ id }: { id: string }) => {
    const getModalData = () => {
      switch (id) {
        case 'modal-conteudo':
          return {
            title: "Estratégia de Conteúdo",
