import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const BASE_SYSTEM_INSTRUCTION = `
    Você é o Agente Greatek de Marketing IA. Especialista em Estratégia B2B para Telecom (ISPs).
    Seu objetivo é transformar referências técnicas em conteúdo de autoridade para a Greatek.
    O foco deve ser: Redução de OPEX, Estabilidade de Rede, Energia Crítica e Wi-Fi 7.
    Tom de voz: Técnico, autoritário, parceiro do dono do provedor.
    Você ajuda uma equipe de 2 pessoas a ter escala de gigante.
`;

export async function generateMarketingContent(prompt: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
            cta: { type: Type.STRING },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error(error);
    return { error: "Erro na geração." };
  }
}

export async function mirrorContent(reference: string) {
  const prompt = `
    ESPELHAMENTO TÉCNICO GREATEK:
    REFERÊNCIA: "${reference}"

    1. Analise o que faz esse conteúdo funcionar (dor técnica ou oportunidade).
    2. Crie um roteiro de Reels (30-60s) adaptado para produtos Greatek.
    3. Use termos: ONU, CTO, Drop, Fusão, Incidente, Latência, OPEX.
    4. Destaque por que a solução Greatek é superior à citada ou implícita.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.8,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING },
            mirroredScript: { type: Type.STRING },
            technicalEdge: { type: Type.STRING },
            cta: { type: Type.STRING }
          },
          required: ["analysis", "mirroredScript", "technicalEdge", "cta"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return { error: "Erro no espelhamento." };
  }
}

