            <span className={`text-[8px] px-2 py-0.5 rounded-full font-mono font-black uppercase ${
              activeSection === item.id ? 'bg-[#0081cc] text-white' : 'bg-slate-100 text-slate-300'
            }`}>
              {item.pill}
            </span>
          </button>
        ))}
