import { GoogleGenAI, Type } from "@google/genai";
import { PRODUCT_CATALOG } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const BASE_SYSTEM_INSTRUCTION = `
    Você é o Agente Greatek de Marketing IA. Especialista em Estratégia B2B para Telecom (ISPs).
    Seu objetivo é transformar referências técnicas em conteúdo de autoridade para a Greatek.
    O foco deve ser: Redução de OPEX, Estabilidade de Rede, Energia Crítica e Wi-Fi 7.
    Tom de voz: Técnico, autoritário, parceiro do dono do provedor.

    REGRAS DE LINGUAGEM CRÍTICAS:
    1. Use obrigatoriamente a norma culta da língua portuguesa.
    2. Garanta que TODOS os acentos (agudo, circunflexo, til, crase) e pontuações estejam presentes e corretos.
    3. Nunca utilize linguagem de chat simplificada ou sem acentos.
    4. Termos técnicos devem ser mantidos, mas o texto ao redor deve ser fluido e legível.
`;

export async function generateMarketingContent(prompt: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
            cta: { type: Type.STRING },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error(error);
    return { error: "Erro na geração." };
  }
}

export async function mirrorContent(reference: string) {
  const catalogContext = JSON.stringify(PRODUCT_CATALOG);

  const prompt = `
    ESPELHAMENTO TÉCNICO GREATEK COM INTELIGÊNCIA DE PRODUTO:
    REFERÊNCIA: "${reference}"
    CATÁLOGO GREATEK DISPONÍVEL: ${catalogContext}

    INSTRUÇÕES:
    1. Analise o conteúdo de referência.
    2. Identifique qual produto do CATÁLOGO GREATEK melhor se encaixa no tema.
    3. Crie um roteiro de Reels (30-60s) integrando esse produto Greatek.
    4. Compare sutilmente com as "Marcas Poderosas" (Power Brands) citadas no catálogo para elevar o valor da Greatek.
    5. Liste "Pontos de Demonstração": O que o apresentador deve MOSTRAR fisicamente no equipamento para o vídeo não ser chato ou monótono.
    6. Liste "Dados Críticos": Informações técnicas que não podem faltar para gerar autoridade.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.8,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING },
            suggestedHardware: { 
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                reason: { type: Type.STRING }
              }
            },
            mirroredScript: { type: Type.STRING },
            demonstrationPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
            criticalData: { type: Type.ARRAY, items: { type: Type.STRING } },
            technicalEdge: { type: Type.STRING },
            cta: { type: Type.STRING }
          },
          required: ["analysis", "suggestedHardware", "mirroredScript", "demonstrationPoints", "criticalData", "technicalEdge", "cta"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error(error);
    return { error: "Erro no espelhamento inteligente." };
  }
}

