    3. Compare com marcas poderosas para mostrar o "Technical Edge" da Greatek.
    4. Garanta acentuação e gramática perfeitas (norma culta).
`;

export async function generateMarketingContent(prompt: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.7,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
