const OpexCalculator: React.FC = () => {
  // Configurações do Provedor
  const [initialCheap, setInitialCheap] = useState(180);
  const [initialGreatek, setInitialGreatek] = useState(580);
  const [visitCost, setVisitCost] = useState(120);
  const [visitsPerYearCheap, setVisitsPerYearCheap] = useState(3);
  const [visitsPerYearGreatek, setVisitsPerYearGreatek] = useState(0.5);
  const [supportCallsPerYear, setSupportCallsPerYear] = useState(12);
  const [callCost, setCallCost] = useState(15);
  const [lifespanCheap, setLifespanCheap] = useState(18);
  const [lifespanGreatek, setLifespanGreatek] = useState(48);

  const stats = useMemo(() => {
    // Cálculo em 24 meses (2 anos) para facilitar a visão
    const months = 24;

    // Hardware Barato
    const opexVisitsCheap = (visitsPerYearCheap * visitCost) * 2;
    const opexSupportCheap = (supportCallsPerYear * callCost) * 2;
    // Custo de reposição (se a vida útil for < 24 meses)
    const replacementCheap = lifespanCheap < 24 ? initialCheap : 0;
    const totalCheap = initialCheap + opexVisitsCheap + opexSupportCheap + replacementCheap;

    // Hardware Greatek
    const opexVisitsGreatek = (visitsPerYearGreatek * visitCost) * 2;
    const opexSupportGreatek = ((supportCallsPerYear * 0.2) * callCost) * 2; // 80% menos chamados
    const totalGreatek = initialGreatek + opexVisitsGreatek + opexSupportGreatek;

    const savings = totalCheap - totalGreatek;
    const roi = (savings / initialGreatek) * 100;

    return { totalCheap, totalGreatek, savings, roi };
  }, [initialCheap, initialGreatek, visitCost, visitsPerYearCheap, visitsPerYearGreatek, supportCallsPerYear, callCost, lifespanCheap]);

  const exportDossie = () => {
