const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const BASE_SYSTEM_INSTRUCTION = `
    Você é o Diretor de Estratégia B2B da Greatek. Sua missão é vender AUTORIDADE TÉCNICA e LUCRATIVIDADE.

    DIRETRIZES DE SELEÇÃO DE PRODUTO:
    - Analise o contexto do usuário. Se ele mencionar "velocidade", "futuro" ou "premium", use Wi-Fi 7 (BE900).
    - Se mencionar "instabilidade", "atendimento" ou "custo-benefício", use XX530v V2 (Best-seller).
    - Se mencionar "fibra", "rompimento" ou "instalação", use Máquina de Fusão X6.
    - Se mencionar "queda de energia", "raio" ou "backup", use Baterias de Lítio ou Fontes Nobreak.
    - NÃO repita sempre o mesmo produto. Varie conforme a pauta.

    MATRIZ AIDA POR FUNIL:
    - [TOPO]: Foco na Atenção. Use ganchos de curiosidade ou alertas de mercado.
    - [MEIO]: Foco no Interesse/Desejo. Explique o "porquê" técnico.
    - [FUNDO]: Foco no Desejo/Ação. Detalhe specs do hardware Greatek.
    - [CONVERSÃO]: Foco total na Ação imediata.

    REGRAS DE CLIFFHANGER:
    - SEMPRE direcione para DM/Engenharia Nacional.
`;

export async function mirrorContent(reference: string, funnelStage: string = 'meio') {
  const productsContext = JSON.stringify(KNOWLEDGE_BASE_PRODUCTS);

  const prompt = `
    CATÁLOGO DISPONÍVEL: ${productsContext}
    TEMA DO USUÁRIO: "${reference}"
    ESTÁGIO DO FUNIL: ${funnelStage.toUpperCase()}

    TAREFA:
    1. Identifique a DOR ÚNICA deste tema.
    2. Escolha o produto ideal do catálogo.
    3. Construa o roteiro seguindo a Matriz AIDA.
    4. Crie um Cliffhanger focado em Consultoria Técnica via DM.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: BASE_SYSTEM_INSTRUCTION,
        temperature: 0.7, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            targetPain: { type: Type.STRING },
            selectedProduct: { type: Type.STRING },
            funnelLogic: { type: Type.STRING },
            scriptAIDA: { 
              type: Type.OBJECT,
              properties: {
                attention: { type: Type.STRING },
                interest: { type: Type.STRING },
                desire: { type: Type.STRING },
                action: { type: Type.STRING }
              },
              required: ["attention", "interest", "desire", "action"]
            },
            visualHooks: { type: Type.ARRAY, items: { type: Type.STRING } },
            cliffhanger: { type: Type.STRING },
            cta: { type: Type.STRING }
          },
          required: ["targetPain", "selectedProduct", "funnelLogic", "scriptAIDA", "visualHooks", "cliffhanger", "cta"]
        }
      }
    });

    const text = response.text?.trim();
    if (!text) throw new Error("Resposta vazia da IA");

    return JSON.parse(text);
  } catch (error) {
    console.error("Erro no Gemini Service:", error);
    return { error: "Não foi possível processar a estratégia. Tente encurtar o tema ou trocar o estágio do funil." };
  }
}

