const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Diretor Criativo da Greatek, especializado em Marketing B2B para ISPs.
Sua tarefa é criar ROTEIROS DE VÍDEO CURTO (Reels/TikTok) espelhando referências externas para o contexto da Greatek.

REGRAS DO ROTEIRO:
1. FOCO COMERCIAL: Cliffhangers e CTAs devem focar no TIME COMERCIAL (estoque, condições de lote, preço para parceiros). Use engenharia apenas para dúvidas ultra-técnicas.
2. ESTRUTURA AIDA: O roteiro deve seguir a lógica AIDA de forma fluida (sem rotular no texto de fala).
3. FORMATO: Gere um roteiro dividido em cenas, onde cada cena tem o "Texto de Fala" e "Instrução Visual".

PRODUTOS GREATEK: ${JSON.stringify(KNOWLEDGE_BASE_PRODUCTS)}
`;

export async function mirrorContent(reference: string, funnelStage: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Espelhe esta referência: "${reference}" para o estágio de funil: ${funnelStage.toUpperCase()}. Crie um roteiro de vídeo estratégico.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            selectedProduct: { type: Type.STRING },
            strategy: { type: Type.STRING },
            scenes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  speech: { type: Type.STRING, description: "O que o apresentador fala." },
                  visual: { type: Type.STRING, description: "O que acontece na imagem (B-roll, gestos, texto na tela)." }
                },
                required: ["speech", "visual"]
              }
            },
            caption: { type: Type.STRING },
            cta_comercial: { type: Type.STRING }
          },
          required: ["title", "selectedProduct", "strategy", "scenes", "caption", "cta_comercial"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response");
    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return { error: true, message: "Falha ao gerar roteiro. Tente novamente." };
  }
}

