import { GoogleGenAI, Type } from "@google/genai";
import { KNOWLEDGE_BASE_PRODUCTS, SPECIAL_PROJECTS_LINKS } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Diretor de Educação Técnica da Greatek. Sua missão é EDUCAR o público ISP e o setor de tecnologia sobre soluções de conectividade.

REGRAS CRÍTICAS:
1. IDIOMA: Use EXCLUSIVAMENTE o português brasileiro. Proibido termos ou frases em inglês, exceto nomes próprios de tecnologias (ex: Wi-Fi 7, PoE, PPSK).
2. FONTES DE INFORMAÇÃO: Baseie-se OBRIGATORIAMENTE nestes links e nos produtos da base:
   ${SPECIAL_PROJECTS_LINKS.join("\n")}
   Não busque outras informações externas nem invente dados técnicos.
3. OBJETIVO: Educação de público e engajamento técnico. NÃO foque em venda direta ou estoque. O objetivo é autoridade técnica.
4. ESTRUTURA DE ROTEIRO: Divida o conteúdo em cenas de produção:
   - CENA (VISUAL): Descrição do que aparece na imagem (gestos, b-roll, animação).
   - FALA (ÁUDIO): Texto fluido para leitura em teleprompter.
5. TEMAS DE FOCO: Unidades Multi-residenciais, Escritórios, Redes de Alta Densidade, Wi-Fi 7, Solução PPSK, Multi-Gigabit e Switches PoE para Vigilância.
`;

export async function mirrorContent(topic: string, funnelStage: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Gere um roteiro educacional sobre: "${topic}". Estágio do Funil: ${funnelStage.toUpperCase()}. Use apenas as fontes autorizadas Greatek.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_conteudo: { type: Type.STRING },
            objetivo_educativo: { type: Type.STRING },
            frase_impacto_inicial: { type: Type.STRING },
            cenas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING, description: "O que vemos na tela (cenário, texto flutuante, cortes)" },
                  audio: { type: Type.STRING, description: "O que o apresentador fala (texto para leitura)" }
                },
                required: ["visual", "audio"]
              }
            },
            legenda_sugerida: { type: Type.STRING },
            pontos_chave_educacao: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_conteudo", "objetivo_educativo", "frase_impacto_inicial", "cenas", "legenda_sugerida"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Resposta vazia da IA");
    return JSON.parse(text);
  } catch (error) {
    console.error("Erro no Gemini:", error);
    return { error: true, message: "Falha na geração do roteiro educacional." };
  }
}

export async function generateMarketingContent(topic: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: topic,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
            cta: { type: Type.STRING },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return { error: true };
  }
}

