import { GoogleGenAI, Type } from "@google/genai";
import { KNOWLEDGE_BASE_PRODUCTS, SPECIAL_PROJECTS_LINKS, PARTNER_COMPANIES } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Especialista Chefe de Educação Técnica da Greatek. Sua missão é criar conteúdo de autoridade que EDUCA o público sobre infraestrutura tecnológica.

REGRAS DE OURO:
1. IDIOMA: Use 100% Português Brasileiro. Proibido termos como "Hook", "CTA", "Body", "Scenes". Use: "Gancho", "Chamada", "Conteúdo", "Cenas".
2. CONHECIMENTO PROFUNDO: Ao falar de um tema (ex: Wi-Fi para Hotéis), você DEVE integrar as parcerias necessárias para o sucesso daquela solução. Se o Wi-Fi é a solução, a ENERGIA (Volt/XPS) é a base. Fale de retificadores, nobreaks e baterias como pilares da estabilidade.
3. FONTES RESTRITAS: Use APENAS as informações destes links e da base de dados Greatek:
   Links Autorizados: ${SPECIAL_PROJECTS_LINKS.join(", ")}
   Parceiros e Produtos: ${JSON.stringify(KNOWLEDGE_BASE_PRODUCTS)}
   Empresas Parceiras: ${JSON.stringify(PARTNER_COMPANIES)}
4. NÃO VENDA: O objetivo é ensinar "Como fazer", "Por que usar" e "Qual a arquitetura correta". Evite linguagem de vendedor. Seja um consultor técnico.
5. FORMATO DE VÍDEO: Divida rigorosamente entre o que o espectador VÊ e o que o apresentador FALA.

TEMAS OBRIGATÓRIOS: Unidades Multi-Residenciais, Escritórios, Redes para Fazendas/Agronegócio, Alta Densidade, Wi-Fi 7, PPSK, Multi-Gigabit, Switches PoE para Vigilância e Sistemas de Energia Crítica.
`;

export async function mirrorContent(pauta: string, estagioFunil: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Pauta Técnica Educativa: "${pauta}". Estágio: ${estagioFunil.toUpperCase()}. Gere um roteiro cinematográfico integrando hardware e energia.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_da_pauta: { type: Type.STRING },
            meta_educativa: { type: Type.STRING },
            gancho_de_atencao: { type: Type.STRING },
            solucao_integrada: { type: Type.STRING, description: "Explicação de como rede e energia trabalham juntas aqui." },
            cenas_de_producao: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING, description: "O que aparece na tela (cenário, hardware, diagramas)" },
                  fala: { type: Type.STRING, description: "O texto exato para o teleprompter em português" }
                },
                required: ["visual", "fala"]
              }
            },
            legenda_para_redes: { type: Type.STRING },
            conceitos_tecnicos_abordados: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_da_pauta", "meta_educativa", "gancho_de_atencao", "cenas_de_producao", "legenda_para_redes", "solucao_integrada"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Resposta vazia da IA");
    return JSON.parse(text);
  } catch (error) {
    console.error("Erro Técnico Gemini:", error);
    return { error: true, message: "Erro ao estruturar roteiro educativo." };
  }
}

export async function generateMarketingContent(topico: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: topico,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo: { type: Type.STRING },
            gancho: { type: Type.STRING },
            conteudo: { type: Type.ARRAY, items: { type: Type.STRING } },
            chamada_para_acao: { type: Type.STRING },
            palavras_chave: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo", "gancho", "conteudo", "chamada_para_acao", "palavras_chave"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return { error: true };
  }
}

