import { GoogleGenAI, Type } from "@google/genai";
import { KNOWLEDGE_BASE_PRODUCTS, SPECIAL_PROJECTS_LINKS, PARTNER_COMPANIES } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Diretor de Educação Técnica da Greatek. Sua missão é criar conteúdo de autoridade técnica que EDUCA o público ISP sobre soluções integradas.

REGRAS CRÍTICAS DE OPERAÇÃO:
1. IDIOMA: Use 100% Português do Brasil. Proibido termos em inglês como "Hook", "CTA", "Body", "Script". Use: "Gancho de Atenção", "Chamada para Ação", "Conteúdo Estratégico", "Roteiro de Produção".
2. FONTES RESTRITAS: Baseie-se APENAS nos links fornecidos e na base de dados interna da Greatek. Não invente informações técnicas nem busque dados externos.
   Links Autorizados: ${SPECIAL_PROJECTS_LINKS.join(", ")}
   Produtos/Parceiros: ${JSON.stringify(KNOWLEDGE_BASE_PRODUCTS)}
   Empresas Parceiras: ${JSON.stringify(PARTNER_COMPANIES)}
3. INTEGRAÇÃO REDE + ENERGIA: Sempre que falar de conectividade (Wi-Fi, Switches, ONTs), você DEVE integrar a necessidade de energia crítica estável (Volt/XPS). Explique como nobreaks, retificadores e baterias sustentam a solução técnica.
4. FOCO EDUCACIONAL: O objetivo é ser um consultor técnico. Não foque em vendas diretas, mas em explicar arquiteturas, redução de OPEX, latência e estabilidade.
5. ESTRUTURA: O roteiro deve separar o que vemos (Visual) do que falamos (Fala para Teleprompter).
`;

export async function mirrorContent(pauta: string, estagioFunil: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Tema Técnico: "${pauta}". Estágio: ${estagioFunil.toUpperCase()}. Gere um roteiro educativo integrando rede e energia com base na base de dados Greatek.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_projeto: { type: Type.STRING },
            meta_educativa: { type: Type.STRING },
            gancho_inicial: { type: Type.STRING },
            arquitetura_integrada: { type: Type.STRING, description: "Explicação de como conectividade e energia (Volt/XPS) se unem aqui." },
            cenas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING, description: "O que vemos na tela" },
                  fala: { type: Type.STRING, description: "O que o apresentador fala" }
                },
                required: ["visual", "fala"]
              }
            },
            legenda_postagem: { type: Type.STRING },
            termos_tecnicos: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_projeto", "meta_educativa", "gancho_inicial", "cenas", "legenda_postagem", "arquitetura_integrada", "termos_tecnicos"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Resposta vazia da IA");
    return JSON.parse(text);
  } catch (error) {
    console.error("Erro Técnico Gemini:", error);
    return { error: true, message: "Erro ao estruturar conhecimento técnico." };
  }
}

