import { GoogleGenAI, Type } from "@google/genai";
import { KNOWLEDGE_BASE_PRODUCTS, SPECIAL_PROJECTS_LINKS, PARTNER_COMPANIES } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Diretor de Educação Técnica da Greatek. Sua missão é criar conteúdo de autoridade técnica que EDUCA o público B2B (ISPs, Engenheiros, Instaladores) sobre o ecossistema completo da marca.

REGRAS OBRIGATÓRIAS DE OPERAÇÃO:
1. IDIOMA: Use 100% Português do Brasil. Proibido termos em inglês como "Hook", "CTA", "Body", "Script". Use: "Gancho de Atenção", "Chamada para Ação", "Conteúdo Estratégico", "Roteiro de Produção".
2. FONTES TOTAIS: Você deve utilizar TODO o banco de dados fornecido. Isso inclui:
   - Instrumentação: Máquinas de Fusão (X6, G-FUSION, Portáteis), OTDR, Clivadores.
   - Conectividade: OLTs, ONTs, Wi-Fi 7, Sistemas Mesh, Omada SDN (B2B).
   - Segurança: Câmeras VIGI, NVRs e Softwares de Monitoramento.
   - Casa Inteligente: Ecossistema Tapo (Sensores, Lâmpadas, Tomadas).
   - Energia Crítica: Volt (Fontes Nobreak, PDUs), XPS (Retificadores, Inversores), Lacerda (Nobreaks Corporativos).
   - Passivos e Infra: Cabos Cabel, Ferragens CG3, DIOs e CTOs Seccon/Think.
3. CONTEXTO TÉCNICO: Não invente especificações. Use os dados exatos do banco de dados (Ex: tempos de fusão, ganhos de antena, potências de retificadores).
4. AUTORIDADE B2B: O objetivo é explicar o "Como" e o "Porquê" técnico. Fale de redução de custos operacionais (OPEX), estabilidade de rede, precisão de medição e escalabilidade.
5. ESTRUTURA DE VÍDEO: Separe o roteiro entre Visual (Direção de cena e hardware) e Fala (Texto para teleprompter).
`;

export async function mirrorContent(pauta: string, estagioFunil: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Pauta Técnica: "${pauta}". Estágio: ${estagioFunil.toUpperCase()}. Gere um roteiro educativo de autoridade usando o ecossistema Greatek pertinente ao tema.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_projeto: { type: Type.STRING },
            categoria_solucao: { type: Type.STRING, description: "Categoria principal do produto/serviço (Ex: Instrumentação, Energia, Segurança)" },
            meta_educativa: { type: Type.STRING },
            gancho_inicial: { type: Type.STRING },
            detalhes_tecnicos_chave: { type: Type.STRING, description: "Destaque de especificações reais do banco de dados usadas no roteiro." },
            cenas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING },
                  fala: { type: Type.STRING }
                },
                required: ["visual", "fala"]
              }
            },
            legenda_postagem: { type: Type.STRING },
            termos_tecnicos: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_projeto", "meta_educativa", "gancho_inicial", "cenas", "legenda_postagem", "categoria_solucao", "termos_tecnicos", "detalhes_tecnicos_chave"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Resposta vazia da IA");
    return JSON.parse(text);
  } catch (error) {
    console.error("Erro Técnico Gemini:", error);
    return { error: true, message: "Erro ao processar conhecimento técnico." };
  }
}

export async function generateMarketingContent(topico: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: topico,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
            cta: { type: Type.STRING },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return { error: true };
  }
}

