import { GoogleGenAI, Type } from "@google/genai";
import { KNOWLEDGE_BASE_PRODUCTS } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Diretor Técnico e Estrategista de Conteúdo da Greatek. Sua missão é criar ROTEIROS DE AUTORIDADE que eduquem donos de ISPs.

REGRAS TÉCNICAS INVIOLÁVEIS:
1. PRODUTOS DISTINTOS: Nunca misture "Máquina de Fusão X6" com "G-FUSION PRO". 
   - A X6 (MF30630X6) possui 6 motores e alinhamento por núcleo/casca.
   - A G-FUSION PRO (MFGFP3201) possui 6 motores, V-Groove ativo e OPM/VFL integrados.
2. LOGICA NARRATIVA: O roteiro deve seguir esta sequência:
   - CENA 1 (DOR): Um problema que faz o ISP perder dinheiro ou ter chamados (ex: atenuação, instabilidade Wi-Fi).
   - CENA 2 (CIÊNCIA): Explicação técnica do "porquê" o problema acontece (ex: desalinhamento de fibra, interferência 2.4GHz).
   - CENA 3 (HARDWARE): Apresentação do produto Greatek/Think/Volt/TP-Link específico.
   - CENA 4 (ROI): Resultado financeiro ou operacional.

3. DOSSIÊ TÉCNICO: Forneça um resumo técnico robusto dos produtos citados para ser usado como consulta rápida.
`;

export async function mirrorContent(pauta: string, estagioFunil: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `TEMA: "${pauta}". ESTÁGIO: ${estagioFunil.toUpperCase()}.
      Crie um roteiro completo e um dossiê técnico. Garanta que os nomes dos produtos estejam corretos conforme o catálogo. O título deve ser forte e sem cortes.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_projeto: { type: Type.STRING },
            categoria: { type: Type.STRING },
            meta_educativa: { type: Type.STRING },
            gancho_inicial: { type: Type.STRING },
            dossie_tecnico: { type: Type.STRING, description: "Resumo detalhado com as specs reais dos produtos citados no roteiro." },
            cenas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING },
                  fala: { type: Type.STRING }
                },
                required: ["visual", "fala"]
              }
            },
            legenda_postagem: { type: Type.STRING },
            termos_tecnicos: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_projeto", "categoria", "meta_educativa", "gancho_inicial", "cenas", "legenda_postagem", "termos_tecnicos", "dossie_tecnico"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Erro Técnico Gemini:", error);
    return { error: true };
  }
}

export async function generateMarketingContent(topico: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: topico,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
            cta: { type: Type.STRING },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return { error: true };
  }
}

