import React, { useState } from 'react';
import { mirrorContent } from '../services/geminiService';
import { cn } from '../lib/utils';
import { jsPDF } from 'jspdf';

const ContentMirror: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [funnelStage, setFunnelStage] = useState('meio');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  const estagios = [
    { id: 'topo', label: 'Topo' },
    { id: 'meio', label: 'Meio' },
    { id: 'fundo', label: 'Fundo' },
  ];

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setResult(null);
    const data = await mirrorContent(topic, funnelStage);
    setResult(data);
    setLoading(false);
  };

  const exportToPDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    const margin = 20;
    const pageWidth = 170;
    let y = 20;

    // Header Principal
    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.setTextColor(4, 53, 97);
    doc.text("GREATEK STRATEGIC DOSSIER", margin, y);
    y += 15;

    // Título Dinâmico
    doc.setFontSize(18);
    doc.setTextColor(0, 129, 204);
    const titleLines = doc.splitTextToSize(result.titulo_projeto.toUpperCase(), pageWidth);
    doc.text(titleLines, margin, y);
    y += (titleLines.length * 8) + 5;

    // Status e Categoria
    doc.setFontSize(10);
    doc.setTextColor(150, 150, 150);
    doc.setFont("helvetica", "normal");
    doc.text(`CATEGORIA: ${result.categoria} | FUNIL: ${funnelStage.toUpperCase()}`, margin, y);
    y += 15;

    // Estratégia e Meta
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.setTextColor(4, 53, 97);
    doc.text("OBJETIVO ESTRATÉGICO:", margin, y);
    y += 7;
    doc.setFont("helvetica", "italic");
    doc.setFontSize(10);
    doc.setTextColor(80, 80, 80);
    const metaLines = doc.splitTextToSize(result.meta_educativa, pageWidth);
    doc.text(metaLines, margin, y);
    y += (metaLines.length * 5) + 12;

    // Dossiê Técnico Específico do Tema
    if (y > 230) { doc.addPage(); y = 20; }
    doc.setFillColor(240, 249, 255);
    doc.rect(margin - 5, y - 5, pageWidth + 10, 45, 'F');
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(0, 129, 204);
    doc.text("DOSSIÊ TÉCNICO DO HARDWARE:", margin, y);
    y += 7;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(4, 53, 97);
    const dossieLines = doc.splitTextToSize(result.dossie_tecnico, pageWidth);
    doc.text(dossieLines, margin, y);
    y += (dossieLines.length * 4.5) + 15;

    // Roteiro Detalhado
    if (y > 220) { doc.addPage(); y = 20; }
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.setTextColor(4, 53, 97);
    doc.text("ROTEIRO DE PRODUÇÃO (SCENE-BY-SCENE):", margin, y);
    y += 10;

    result.cenas.forEach((cena: any, index: number) => {
      if (y > 250) { doc.addPage(); y = 20; }

      doc.setFontSize(9);
      doc.setTextColor(0, 129, 204);
      doc.text(`CENA ${index + 1}`, margin, y);
      y += 5;

      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.setTextColor(150, 150, 150);
      const visualLines = doc.splitTextToSize(`VISUAL: ${cena.visual}`, pageWidth);
      doc.text(visualLines, margin, y);
      y += (visualLines.length * 4.5) + 2;

      doc.setTextColor(4, 53, 97);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      const falaLines = doc.splitTextToSize(`FALA: "${cena.fala}"`, pageWidth);
      doc.text(falaLines, margin, y);
      y += (falaLines.length * 5) + 10;
    });

    doc.save(`greatek_dossie_${result.titulo_projeto.toLowerCase().replace(/\s+/g, '_')}.pdf`);
  };

  return (
    <div id="mirror" className="py-24 border-t border-slate-100 bg-white">
      <div className="max-w-7xl mx-auto px-6">

        <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-8">
          <div>
            <div className="flex items-center gap-3 mb-4">
              <span className="w-10 h-[2px] bg-[#0081cc]"></span>
              <span className="text-[10px] font-black text-[#0081cc] uppercase tracking-[0.4em]">Explorador de Ecossistema</span>
            </div>
            <h2 className="text-6xl font-black text-[#043561] tracking-tighter italic uppercase leading-none">
              Content <span className="text-[#0081cc]">Mirror</span>
            </h2>
          </div>

          <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
            {estagios.map(s => (
              <button
                key={s.id}
                onClick={() => setFunnelStage(s.id)}
                className={cn(
                  "px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all",
                  funnelStage === s.id ? "bg-[#043561] text-white shadow-lg" : "text-slate-400 hover:text-slate-600"
                )}
              >
                {s.label}
              </button>
            ))}
          </div>
        </header>

        {/* Input Inteligente */}
        <div className="mb-16 relative group">
          <textarea
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Qual o tema técnico de hoje? (Ex: Wi-Fi 7 para hotéis, Energia Solar em POPs, Switches Omada para empresas...)"
            className="w-full h-24 bg-slate-50 border-b-2 border-slate-200 focus:border-[#0081cc] p-6 text-xl font-bold text-[#043561] outline-none transition-all placeholder:text-slate-300 resize-none"
          />
          <div className="absolute right-4 bottom-4 flex gap-3">
            <button 
              onClick={handleGenerate}
              disabled={loading || topic.length < 3}
              className="bg-[#0081cc] text-white text-[10px] font-black uppercase tracking-widest px-8 py-4 rounded-full shadow-lg hover:bg-[#043561] transition-all disabled:opacity-50 flex items-center gap-2"
            >
              {loading ? <span className="animate-pulse italic">Analisando Ecossistema...</span> : "Explorar Tema"}
            </button>
          </div>
        </div>

        {result && !result.error && (
          <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">

            {/* Header de Resultados Flexível */}
            <div className="mb-12 flex flex-col lg:flex-row lg:items-start justify-between gap-8 border-b border-slate-50 pb-10">
              <div className="flex-1 min-w-0">
                <div className="flex flex-wrap gap-2 mb-6">
                  <span className="px-3 py-1 bg-[#043561] text-[#00ff00] text-[9px] font-black uppercase tracking-widest rounded">
                    {result.categoria}
                  </span>
                  <span className="px-3 py-1 bg-[#0081cc] text-white text-[9px] font-black uppercase tracking-widest rounded">
                    FOCO: {funnelStage.toUpperCase()}
                  </span>
                </div>
                <h3 className="text-4xl md:text-5xl lg:text-6xl font-black text-[#043561] tracking-tighter uppercase italic leading-[1.05] break-words">
                  {result.titulo_projeto}
                </h3>
              </div>

              <button 
                onClick={exportToPDF}
                className="shrink-0 flex items-center gap-3 px-10 py-5 bg-emerald-500 hover:bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-500/20 transition-all active:scale-95 group"
              >
                <svg className="w-5 h-5 group-hover:rotate-12 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                <span className="text-[10px] font-black uppercase tracking-widest">Download PDF Técnico</span>
              </button>
            </div>

            {/* Layout em Grade: Estratégia e Dossiê */}
            <div className="grid grid-cols-1 md:grid-cols-12 gap-10 mb-16 py-4">
              <div className="md:col-span-7">
                <label className="text-[9px] font-black text-[#0081cc] uppercase tracking-widest block mb-4 italic">Estratégia Narrativa</label>
                <p className="text-slate-500 font-bold text-xl leading-snug italic pr-8 mb-8">
                  "{result.meta_educativa}"
                </p>
                <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
                  <label className="text-[9px] font-black text-[#043561] uppercase tracking-widest block mb-2 italic">Gancho de Vídeo</label>
                  <p className="text-2xl font-black text-[#043561] italic tracking-tighter leading-none uppercase pr-4">"{result.gancho_inicial}"</p>
                </div>
              </div>
              <div className="md:col-span-5">
                <div className="bg-[#043561] p-8 rounded-[3.5rem] text-white h-full border border-white/5 relative overflow-hidden group">
                  <div className="absolute -top-4 -right-4 text-white/5 text-9xl font-black italic select-none">DATA</div>
                  <label className="text-[9px] font-black text-[#00ff00] uppercase tracking-widest block mb-4 italic relative z-10">Dossiê Técnico do Tema</label>
                  <p className="text-[11px] font-bold leading-relaxed italic relative z-10 text-white/80 whitespace-pre-line">
                    {result.dossie_tecnico}
