                </div>
              </div>
            </div>

            {/* Tabela de Produção Fluida */}
            <div className="mb-20">
              <div className="grid grid-cols-12 text-[9px] font-black text-slate-300 uppercase tracking-widest border-b border-slate-200 pb-4 mb-8 px-6">
