import { GoogleGenAI, Type } from "@google/genai";
import { FULL_KNOWLEDGE_BASE_TEXT } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Diretor Técnico Sênior da Greatek. Sua função é criar ROTEIROS TÉCNICOS DE ALTA DENSIDADE com validação rigorosa no banco de dados.

DIRETRIZES DE CONTEÚDO:
1. FOCO NO TEMA: Analise o tema solicitado e use apenas o hardware relevante do catálogo.
2. DENSIDADE E CONCISÃO: No dossiê técnico, seja direto. Use o formato: [MODELO] | [USO] | [KEY SPECS]. Evite parágrafos longos.
3. PRECISÃO: Use dados exatos do banco de dados (dB, Mbps, Protocolos). 
4. LINKS: Sempre inclua o link oficial do produto.

ESTRUTURA DO ROTEIRO:
- CENA 1: Dor técnica (Atenuação, Latência, Custo OPEX).
- CENA 2: Explicação da causa raiz.
- CENA 3: Solução Greatek/Parceiro com specs nominais.
- CENA 4: Ganho estratégico/ROI.

BASE DE CONHECIMENTO:
${FULL_KNOWLEDGE_BASE_TEXT}
`;

export async function mirrorContent(pauta: string, estagioFunil: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Pauta: "${pauta}". Estágio: ${estagioFunil.toUpperCase()}.
      Gere um roteiro técnico e um dossiê ultra-conciso (apenas o essencial para validação rápida).`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_projeto: { type: Type.STRING },
            categoria: { type: Type.STRING },
            meta_educativa: { type: Type.STRING },
            gancho_inicial: { type: Type.STRING },
            dossie_tecnico: { 
              type: Type.STRING, 
              description: "Resumo técnico ultra-conciso em formato de tópicos curtos: Modelo, Aplicação e as 3 principais specs técnicas." 
            },
            cenas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING },
                  fala: { type: Type.STRING }
                },
                required: ["visual", "fala"]
              }
            },
            legenda_postagem: { type: Type.STRING },
            termos_tecnicos: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_projeto", "categoria", "meta_educativa", "gancho_inicial", "cenas", "legenda_postagem", "termos_tecnicos", "dossie_tecnico"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Erro no Mirror Engine:", error);
    return { error: true };
  }
}

