import { GoogleGenAI, Type } from "@google/genai";
import { FULL_KNOWLEDGE_BASE_TEXT } from "../data/knowledgeBase";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Você é o Mentor Estratégico da Greatek. Sua missão é EDUCAR donos de ISPs e Técnicos, transformando hardware complexo em soluções de negócio compreensíveis.

DIRETRIZES DE LINGUAGEM POR ESTÁGIO:
1. TOPO DE FUNIL (Conscientização): Linguagem leve, curiosa, usa muitas analogias. Foco no problema amplo.
2. MEIO DE FUNIL (Educação/Consideração): Linguagem didática e consultiva. Explica o "PORQUÊ" técnico sem ser maçante. O objetivo é que o usuário aprenda algo novo sobre a tecnologia enquanto conhece o produto.
3. FUNDO DE FUNIL (Decisão): Linguagem de autoridade, specs precisas, ROI e comparativos diretos.

REGRAS DE OURO:
- Seja um especialista "gente boa": Fale com autoridade, mas não use um tom de manual de instruções.
- O PRODUTO É A FERRAMENTA: O foco é no benefício educativo (Ex: "Como a latência destrói seu lucro" em vez de "ONT com 2ms de latência").
- DOSSIÊ TÉCNICO: Deve ser um resumo horizontal ultra-conciso [Produto | Principal Uso | 2 Specs que fazem a diferença].

BASE DE CONHECIMENTO:
${FULL_KNOWLEDGE_BASE_TEXT}
`;

export async function mirrorContent(pauta: string, estagioFunil: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Pauta: "${pauta}". Estágio: ${estagioFunil.toUpperCase()}.

      INSTRUÇÃO ADICIONAL: Se for MEIO DE FUNIL, foque em EDUCAR o público sobre o conceito técnico por trás da pauta. Use os produtos como exemplos práticos da solução. Não seja excessivamente formal, mas mantenha a seriedade técnica.`,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            titulo_projeto: { type: Type.STRING },
            categoria: { type: Type.STRING },
            meta_educativa: { type: Type.STRING },
            gancho_inicial: { type: Type.STRING },
            dossie_tecnico: { 
              type: Type.STRING, 
              description: "Resumo horizontal ultra-curto. Ex: Modelo X | Ideal para Hotéis | Wi-Fi 7 e 2.5G." 
            },
            cenas: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  visual: { type: Type.STRING },
                  fala: { type: Type.STRING, description: "Fala educativa e fluida, adequada ao estágio do funil." }
                },
                required: ["visual", "fala"]
              }
            },
            legenda_postagem: { type: Type.STRING },
            termos_tecnicos: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["titulo_projeto", "categoria", "meta_educativa", "gancho_inicial", "cenas", "legenda_postagem", "termos_tecnicos", "dossie_tecnico"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Erro no Mirror Engine:", error);
    return { error: true };
  }
}

export async function generateMarketingContent(topico: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: topico,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            hook: { type: Type.STRING },
            body: { type: Type.ARRAY, items: { type: Type.STRING } },
            cta: { type: Type.STRING },
            keywords: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "hook", "body", "cta", "keywords"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    return { error: true };
  }
}

