import React, { useState } from 'react';
import { mirrorContent } from '../services/geminiService.ts';
import { cn } from '../lib/utils.ts';
import { jsPDF } from 'jspdf';

const ContentMirror: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [funnelStage, setFunnelStage] = useState('meio');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  const estagios = [
    { id: 'topo', label: 'Topo' },
    { id: 'meio', label: 'Meio' },
    { id: 'fundo', label: 'Fundo' },
  ];

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setResult(null);
    const data = await mirrorContent(topic, funnelStage);
    setResult(data);
    setLoading(false);
  };

  const exportToPDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    const margin = 20;
    const pageWidth = 170;
    let y = 20;

    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.setTextColor(4, 53, 97);
    doc.text("GREATEK CONTENT PLANNER 2026", margin, y);
    y += 15;

    doc.setFontSize(14);
    doc.setTextColor(0, 129, 204);
    const titleLines = doc.splitTextToSize(result.titulo_projeto.toUpperCase(), pageWidth);
    doc.text(titleLines, margin, y);
    y += (titleLines.length * 7) + 5;

    doc.setFontSize(9);
    doc.setTextColor(150, 150, 150);
    doc.text(`CONTEÚDO PARA: ${funnelStage.toUpperCase()} DE FUNIL`, margin, y);
    y += 10;

    doc.setFillColor(245, 247, 250);
    doc.rect(margin - 5, y - 5, pageWidth + 10, 30, 'F');
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(0, 129, 204);
    doc.text("HARDWARE EM DESTAQUE:", margin, y);
    y += 6;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(4, 53, 97);
    const dLines = doc.splitTextToSize(result.dossie_tecnico, pageWidth);
    doc.text(dLines, margin, y);
    y += (dLines.length * 5) + 12;

    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(4, 53, 97);
    doc.text("ROTEIRO ESTRATÉGICO:", margin, y);
    y += 10;

    result.cenas.forEach((cena: any, index: number) => {
      if (y > 250) { doc.addPage(); y = 20; }
      doc.setFontSize(8);
      doc.setTextColor(0, 129, 204);
      doc.text(`CENA ${index + 1}`, margin, y);
      y += 5;
      doc.setFont("helvetica", "bold");
      doc.setFontSize(9.5);
      doc.setTextColor(4, 53, 97);
      const falaLines = doc.splitTextToSize(`"${cena.fala}"`, pageWidth);
      doc.text(falaLines, margin, y);
      y += (falaLines.length * 5) + 8;
    });

    doc.save(`greatek_planejamento_${funnelStage}_${result.titulo_projeto.toLowerCase().replace(/\s+/g, '_')}.pdf`);
  };

  return (
    <div id="mirror" className="py-24 border-t border-slate-100 bg-white overflow-hidden">
      <div className="max-w-7xl mx-auto px-6">

        <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-8">
          <div>
            <div className="flex items-center gap-3 mb-4">
              <span className="w-10 h-[2px] bg-[#0081cc]"></span>
              <span className="text-[10px] font-black text-[#0081cc] uppercase tracking-[0.4em]">IA Estratégica & Educação</span>
            </div>
            <h2 className="text-6xl font-black text-[#043561] tracking-tighter italic uppercase leading-none">
              Content <span className="text-[#0081cc]">Mirror</span>
            </h2>
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl">
            {estagios.map(s => (
              <button
                key={s.id}
                onClick={() => setFunnelStage(s.id)}
                className={cn(
                  "px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all",
                  funnelStage === s.id ? "bg-[#043561] text-white shadow-xl" : "text-slate-400 hover:text-slate-600"
                )}
              >
                {s.label}
              </button>
            ))}
          </div>
        </header>

        {/* Input Inteligente */}
        <div className="mb-12 relative group">
          <textarea
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Qual conceito técnico vamos ensinar hoje? (Ex: Como o Wi-Fi 7 elimina gargalos em prédios comerciais...)"
            className="w-full h-24 bg-slate-50 border-b-2 border-slate-200 focus:border-[#0081cc] p-6 text-xl font-bold text-[#043561] outline-none transition-all placeholder:text-slate-300 resize-none"
          />
          <div className="absolute right-4 bottom-4">
            <button 
              onClick={handleGenerate}
              disabled={loading || topic.length < 3}
              className="bg-[#0081cc] hover:bg-[#043561] text-white text-[10px] font-black uppercase tracking-widest px-10 py-4 rounded-full shadow-lg transition-all flex items-center gap-3 disabled:opacity-50"
            >
              {loading ? "Processando Linguagem..." : "Gerar Roteiro Educativo"}
            </button>
          </div>
        </div>

        {result && !result.error && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">

