              </div>
              <button 
                onClick={exportToPDF}
                className="shrink-0 flex items-center gap-3 px-8 py-4 bg-[#043561] text-white rounded-2xl shadow-xl hover:bg-[#0081cc] transition-all active:scale-95"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                <span className="text-[9px] font-black uppercase tracking-widest">Exportar Guia</span>
              </button>
            </div>

            {/* Dossiê Técnico Horizontal - Ultra Slim */}
            <div className="mb-10">
               <div className="bg-[#043561] rounded-[2rem] p-6 text-white shadow-2xl relative overflow-hidden group">
                  <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                    <svg className="w-24 h-24" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                  <div className="flex flex-col md:flex-row md:items-center gap-8 relative z-10">
