import React, { useEffect } from 'react';

interface SidebarProps {
  activeSection: string;
  setActiveSection: (section: string) => void;
  onOpenModal: (id: string) => void;
  onReset: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeSection, setActiveSection, onOpenModal, onReset }) => {
  const navItems = [
    { id: 'start', label: '🚀 Start Strategy', pill: 'NOW' },
    { id: 'visao', label: 'Visão & Metas', pill: 'Start' },
    { id: 'diagnostico', label: 'Análise SWOT', pill: 'Real' },
    { id: 'pilares', label: '4 Pilares', pill: 'Core' },
    { id: 'leads', label: 'Lead Intelligence', pill: 'Data' },
    { id: 'mirror', label: 'Content Mirror', pill: 'IA' },
    { id: 'opex-calc', label: 'Calculadora OPEX', pill: 'ROI' },
    { id: 'pipeline', label: 'Timeline Anual', pill: 'Time' },
    { id: 'assistant', label: 'Assistente IA', pill: 'Gemini' },
    { id: 'execucao', label: 'Sprint Semanal', pill: 'SOP' },
    { id: 'contingencia', label: 'Contingência', pill: 'Risk' },
  ];

  // Efeito de ScrollSpy para detectar a seção ativa
  useEffect(() => {
    const observerOptions = {
      root: null,
      rootMargin: '-20% 0px -70% 0px', // Ajusta a "janela" de detecção
      threshold: 0
    };

    const observerCallback = (entries: IntersectionObserverEntry[]) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    };

    const observer = new IntersectionObserver(observerCallback, observerOptions);

    navItems.forEach((item) => {
      const element = document.getElementById(item.id);
      if (element) observer.observe(element);
    });

    return () => observer.disconnect();
  }, [setActiveSection]);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 40;
      const elementPosition = element.getBoundingClientRect().top + window.pageYOffset;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    }
  };

  return (
    <aside className="w-72 hidden lg:flex flex-col border-r border-slate-100 bg-white h-screen sticky top-0 p-8 z-40">
      <div className="flex items-center gap-4 p-5 mb-10 bg-[#043561] rounded-3xl shadow-xl shadow-[#043561]/10">
        <div className="w-10 h-10 bg-[#0081cc] rounded-xl flex items-center justify-center font-black text-white text-xl">G</div>
        <div>
          <h1 className="text-sm font-black leading-tight text-white tracking-tighter uppercase">Greatek OS</h1>
          <p className="text-[9px] text-[#0081cc] uppercase tracking-widest font-black">Marketing 2026</p>
        </div>
      </div>

      <nav className="flex flex-col gap-1 overflow-y-auto pr-2 custom-scrollbar">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => scrollToSection(item.id)}
            className={`flex items-center justify-between px-5 py-3 rounded-2xl transition-all duration-300 group shrink-0 ${
              activeSection === item.id 
                ? 'bg-[#0081cc] text-white shadow-lg shadow-[#0081cc]/20' 
                : 'text-slate-400 hover:text-[#043561] hover:bg-slate-50'
            }`}
          >
            <span className={`text-[11px] font-black uppercase tracking-tight ${activeSection === item.id ? 'text-white' : ''}`}>{item.label}</span>
            <span className={`text-[8px] px-2 py-0.5 rounded-full font-mono font-black uppercase transition-colors ${
              activeSection === item.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-300 group-hover:bg-slate-200'
            }`}>
              {item.pill}
            </span>
          </button>
        ))}
      </nav>

      <div className="mt-auto pt-6 border-t border-slate-50">
        <div className="bg-slate-50 p-5 rounded-[2rem]">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Status da Equipe</p>
          <div className="flex items-center gap-3">
            <div className="flex -space-x-2">
              <div className="w-8 h-8 rounded-full bg-[#043561] border-2 border-white flex items-center justify-center text-[10px] text-white font-black">M1</div>
              <div className="w-8 h-8 rounded-full bg-[#0081cc] border-2 border-white flex items-center justify-center text-[10px] text-white font-black">M2</div>
            </div>
            <div className="flex flex-col">
              <span className="text-[9px] font-black text-[#043561] uppercase leading-none">Modo Operacional</span>
              <span className="text-[9px] font-bold text-emerald-500 uppercase flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                Alta Performance
              </span>
            </div>
          </div>
        </div>
      </div>
    </aside>
  );
