const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('start');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [modal, setModal] = useState<{ id: string; open: boolean }>({ id: 'none', open: false });

  useEffect(() => {
    const savedTasks = localStorage.getItem('greatek_tasks_2026_v10');
    if (savedTasks) {
      try {
        const parsed = JSON.parse(savedTasks);
        setTasks(Array.isArray(parsed) ? parsed : WEEKLY_TASKS);
      } catch (e) {
        setTasks(WEEKLY_TASKS);
      }
    } else {
      setTasks(WEEKLY_TASKS);
    }
  }, []);

  useEffect(() => {
    if (tasks && tasks.length > 0) {
      localStorage.setItem('greatek_tasks_2026_v10', JSON.stringify(tasks));
    }
  }, [tasks]);

  const [currentQuoteIndex, setCurrentQuoteIndex] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentQuoteIndex(prev => (prev + 1) % MOTIVATIONAL_QUOTES.length);
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

