import React, { useEffect, useState } from 'react';

interface SidebarProps {
  activeSection: string;
  setActiveSection: (section: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeSection, setActiveSection }) => {
  const navItems = [
    { id: 'start', label: '🚀 Start Strategy', pill: 'NOW' },
    { id: 'visao', label: 'Visão & Metas', pill: 'Goal' },
    { id: 'diagnostico', label: 'Análise SWOT', pill: 'Data' },
    { id: 'pilares', label: '4 Pilares', pill: 'Core' },
    { id: 'leads', label: 'Lead Intelligence', pill: 'Sale' },
    { id: 'mirror', label: 'Content Mirror', pill: 'IA' },
    { id: 'opex-calc', label: 'Calculadora OPEX', pill: 'ROI' },
    { id: 'pipeline', label: 'Timeline Anual', pill: 'Plan' },
    { id: 'assistant', label: 'Assistente IA', pill: 'Chat' },
    { id: 'execucao', label: 'Sprint Semanal', pill: 'SOP' },
    { id: 'contingencia', label: 'Contingência', pill: 'Risk' },
  ];

  useEffect(() => {
    const observerOptions = {
      root: null,
      rootMargin: '-20% 0px -70% 0px',
      threshold: 0
    };

    const observerCallback = (entries: IntersectionObserverEntry[]) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    };

    const observer = new IntersectionObserver(observerCallback, observerOptions);

    navItems.forEach((item) => {
      const el = document.getElementById(item.id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [setActiveSection]);

  const scrollTo = (id: string) => {
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <aside className="w-72 hidden lg:flex flex-col border-r border-slate-100 bg-white h-screen sticky top-0 p-8 z-40 shrink-0">
      <div className="flex items-center gap-4 p-5 mb-10 bg-[#043561] rounded-3xl shadow-xl">
        <div className="w-10 h-10 bg-[#0081cc] rounded-xl flex items-center justify-center font-black text-white text-xl">G</div>
        <div>
          <h1 className="text-sm font-black leading-tight text-white uppercase tracking-tighter">Greatek OS</h1>
          <p className="text-[9px] text-[#0081cc] uppercase tracking-widest font-black">Admin 2026</p>
        </div>
      </div>

      <nav className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-1">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => scrollTo(item.id)}
            className={`w-full flex items-center justify-between px-5 py-3 rounded-2xl transition-all duration-300 group shrink-0 ${
              activeSection === item.id 
                ? 'bg-[#0081cc] text-white shadow-lg' 
                : 'text-slate-400 hover:text-[#043561] hover:bg-slate-50'
            }`}
          >
            <span className="text-[10px] font-black uppercase tracking-tight">{item.label}</span>
            <span className={`text-[8px] px-2 py-0.5 rounded-full font-mono font-black uppercase ${
              activeSection === item.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-300'
            }`}>
              {item.pill}
            </span>
          </button>
        ))}
      </nav>

      <div className="mt-8 pt-6 border-t border-slate-50">
        <div className="bg-slate-50 p-5 rounded-3xl">
          <div className="flex items-center gap-3">
             <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
             <span className="text-[10px] font-black text-[#043561] uppercase tracking-widest">Equipe On-line</span>
          </div>
        </div>
      </div>
    </aside>
  );
};

