import React, { useState, useMemo } from 'react';

const OpexCalculator: React.FC = () => {
  // Entradas Globais
  const [numClients, setNumClients] = useState(1000);
  const [visitCost, setVisitCost] = useState(100);

  // Módulo 1: Suporte & Wi-Fi
  const [visitsPer100, setVisitsPer100] = useState(5);
  const [avoidedPer100, setAvoidedPer100] = useState(3);

  // Módulo 2: Energia POP (10 Anos)
  const [numPops, setNumPops] = useState(5);
  const [batteriesPerPop, setBatteriesPerPop] = useState(4);
  const [priceVrla, setPriceVrla] = useState(600);
  const [priceLithium, setPriceLithium] = useState(2500);
  const [laborCost, setLaborCost] = useState(100);

  // Módulo 3: Escalabilidade (>600M)
  const [percentHighPlans, setPercentHighPlans] = useState(25);
  const [percentUpgradeNeeded, setPercentUpgradeNeeded] = useState(20);
  const [priceBasic, setPriceBasic] = useState(180);
  const [priceFutureProof, setPriceFutureProof] = useState(350);

  const stats = useMemo(() => {
    const blocks = numClients / 100;

    // Mod 1
    const visitsAvoidedMonthly = blocks * avoidedPer100;
    const mod1SavingsMonthly = visitsAvoidedMonthly * visitCost;

    // Mod 2 (Cálculo 10 Anos - 120 meses)
    const trocasVrla = 5; // Cada 2 anos
    const trocasLithium = 1; // Instalação inicial
    const costVrla10y = ((priceVrla * batteriesPerPop * trocasVrla) + (laborCost * trocasVrla)) * numPops;
    const costLithium10y = ((priceLithium * batteriesPerPop * trocasLithium) + (laborCost * trocasLithium)) * numPops;
    const mod2Savings10y = costVrla10y - costLithium10y;
    const mod2SavingsMonthly = mod2Savings10y / 120;

    // Mod 3
    const clients600 = numClients * (percentHighPlans / 100);
    const clientsUpgradeTroca = clients600 * (percentUpgradeNeeded / 100);
    const mod3SavingsOpex = clientsUpgradeTroca * visitCost;
    const mod3InvestExtra = clients600 * (priceFutureProof - priceBasic);
    const mod3SaldoAnual = mod3SavingsOpex - mod3InvestExtra;
    const mod3Mensalizado = mod3SaldoAnual / 12;

    const totalMonthly = mod1SavingsMonthly + mod2SavingsMonthly + mod3Mensalizado;

    return {
      mod1: { monthly: mod1SavingsMonthly, avoided: visitsAvoidedMonthly },
      mod2: { tenYear: mod2Savings10y, monthly: mod2SavingsMonthly, trocasEvitadas: (trocasVrla - trocasLithium) * numPops },
      mod3: { opex: mod3SavingsOpex, capex: mod3InvestExtra, saldo: mod3SaldoAnual, mensal: mod3Mensalizado },
      totalMonthly,
      perClient: totalMonthly / numClients
    };
  }, [numClients, visitCost, avoidedPer100, numPops, batteriesPerPop, priceVrla, priceLithium, laborCost, percentHighPlans, percentUpgradeNeeded, priceBasic, priceFutureProof]);

  return (
    <div id="opex-calc" className="py-24 scroll-mt-24">
      <div className="bg-slate-50 border border-slate-100 rounded-[4rem] p-12 lg:p-20">
        <header className="mb-20">
          <h2 className="text-6xl font-black text-[#043561] tracking-tighter uppercase mb-6 italic">Calculadora <span className="text-[#0081cc]">OPEX Pro</span></h2>
          <p className="text-slate-500 text-xl font-medium max-w-2xl leading-relaxed">Demonstração matemática de ROI: Hardware de elite como centro de lucro operacional.</p>
        </header>

        {/* Entradas Globais */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-20 bg-white p-10 rounded-[3rem] shadow-sm">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Clientes Ativos</label>
            <input type="number" value={numClients} onChange={e => setNumClients(Number(e.target.value))} className="w-full text-3xl font-black text-[#043561] border-b-2 border-slate-100 focus:border-[#0081cc] outline-none pb-2" />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Custo Visita Técnica (R$)</label>
            <input type="number" value={visitCost} onChange={e => setVisitCost(Number(e.target.value))} className="w-full text-3xl font-black text-[#0081cc] border-b-2 border-slate-100 focus:border-[#0081cc] outline-none pb-2" />
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Módulo 1 */}
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 flex flex-col group hover:border-[#0081cc] transition-all">
            <span className="text-[#0081cc] text-[10px] font-black uppercase mb-6 tracking-[0.2em]">Módulo 01: Suporte & Wi-Fi</span>
            <div className="flex-1 space-y-6">
              <p className="text-sm font-bold text-slate-400 leading-tight italic">Gestão remota via TAUC e monitoramento SkyWatch reduzem deslocamentos.</p>
              <div className="bg-slate-50 p-6 rounded-2xl">
                <span className="text-[9px] font-black text-[#043561] uppercase block mb-1">Visitas evitadas/mês</span>
                <span className="text-2xl font-black text-[#043561]">{stats.mod1.avoided.toFixed(0)}</span>
              </div>
            </div>
            <div className="mt-10 pt-10 border-t border-slate-50 text-right">
              <span className="text-[10px] font-black text-slate-300 uppercase block">Economia Anual</span>
              <span className="text-3xl font-black text-[#043561]">R$ {(stats.mod1.monthly * 12).toLocaleString()}</span>
            </div>
          </div>

          {/* Módulo 2 */}
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 flex flex-col group hover:border-[#0081cc] transition-all">
            <span className="text-emerald-500 text-[10px] font-black uppercase mb-6 tracking-[0.2em]">Módulo 02: Energia POP (10 Anos)</span>
            <div className="flex-1 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[9px] font-black text-slate-300 uppercase">POPs</label>
                  <input type="number" value={numPops} onChange={e => setNumPops(Number(e.target.value))} className="w-full font-black text-[#043561]" />
                </div>
                <div>
                  <label className="text-[9px] font-black text-slate-300 uppercase">Preço Lítio</label>
                  <input type="number" value={priceLithium} onChange={e => setPriceLithium(Number(e.target.value))} className="w-full font-black text-emerald-500" />
                </div>
              </div>
              <p className="text-[11px] font-bold text-slate-400">Vida VRLA: 2 anos | Vida Lítio: 10 anos. Trocas evitadas: <span className="text-emerald-500 font-black">{stats.mod2.trocasEvitadas}</span></p>
            </div>
            <div className="mt-10 pt-10 border-t border-slate-50 text-right">
              <span className="text-[10px] font-black text-slate-300 uppercase block">Economia em 10 anos</span>
              <span className="text-3xl font-black text-emerald-500 uppercase tracking-tighter">R$ {stats.mod2.tenYear.toLocaleString()}</span>
            </div>
          </div>

          {/* Módulo 3 */}
          <div className="bg-[#043561] p-10 rounded-[3.5rem] text-white flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-6 opacity-10 font-black text-4xl">UP</div>
            <span className="text-[#00ff00] text-[10px] font-black uppercase mb-6 tracking-[0.2em]">Módulo 03: Escalabilidade</span>
            <div className="flex-1 space-y-6 relative z-10">
              <div className="bg-white/5 p-4 rounded-xl">
                <label className="text-[9px] font-black text-white/40 uppercase block mb-1">% Planos > 600M</label>
                <input type="number" value={percentHighPlans} onChange={e => setPercentHighPlans(Number(e.target.value))} className="bg-transparent border-none font-black text-white w-full outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-4 text-[10px]">
                <div><span className="opacity-50 block">Economia OPEX</span><span className="font-black">R$ {stats.mod3.opex.toLocaleString()}</span></div>
                <div><span className="opacity-50 block">Invest. CAPEX</span><span className="font-black text-rose-400">R$ {stats.mod3.capex.toLocaleString()}</span></div>
              </div>
            </div>
            <div className="mt-10 pt-10 border-t border-white/10 text-right relative z-10">
              <span className="text-[10px] font-black text-white/40 uppercase block">Saldo Estimado (Anual)</span>
              <span className={`text-3xl font-black ${stats.mod3.saldo >= 0 ? 'text-[#00ff00]' : 'text-rose-400'}`}>R$ {stats.mod3.saldo.toLocaleString()}</span>
            </div>
          </div>
        </div>

        {/* Resumo Dashboard */}
        <div className="mt-12 bg-white p-12 rounded-[4rem] border border-slate-100 flex flex-col md:flex-row items-center justify-between gap-10 shadow-xl">
           <div>
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-4">Economia Total Mensalizada</h4>
              <div className="flex items-baseline gap-4">
                 <span className="text-6xl font-black text-[#043561] tracking-tighter italic">R$ {stats.totalMonthly.toLocaleString()}</span>
                 <span className="text-[#00ff00] font-black text-xl animate-pulse">✓</span>
              </div>
           </div>
           <div className="text-right">
              <span className="text-[10px] font-black text-[#0081cc] uppercase tracking-widest block mb-2">Impacto por Cliente/Mês</span>
              <span className="text-4xl font-black text-[#043561]">R$ {stats.perClient.toFixed(2)}</span>
           </div>
        </div>
      </div>
    </div>
  );
};

