import React, { useState } from 'react';
import { mirrorContent } from '../services/geminiService.ts';
import { cn } from '../lib/utils.ts';
import { jsPDF } from 'jspdf';

const ContentMirror: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [funnelStage, setFunnelStage] = useState('meio');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);

  const estagios = [
    { id: 'topo', label: 'Topo' },
    { id: 'meio', label: 'Meio' },
    { id: 'fundo', label: 'Fundo' },
  ];

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    setResult(null);
    const data = await mirrorContent(topic, funnelStage);
    setResult(data);
    setLoading(false);
  };

  return (
    <div id="mirror" className="py-24 border-t border-slate-100 bg-white overflow-hidden">
      <div className="max-w-7xl mx-auto px-6">
        <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-8">
          <div>
            <div className="flex items-center gap-3 mb-4">
              <span className="w-10 h-[2px] bg-[#0081cc]"></span>
              <span className="text-[10px] font-black text-[#0081cc] uppercase tracking-[0.4em]">IA Estratégica & Educação</span>
            </div>
            <h2 className="text-6xl font-black text-[#043561] tracking-tighter italic uppercase leading-none">Content <span className="text-[#0081cc]">Mirror</span></h2>
          </div>
          <div className="flex bg-slate-100 p-1.5 rounded-2xl">
            {estagios.map(s => (
              <button key={s.id} onClick={() => setFunnelStage(s.id)} className={cn("px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all", funnelStage === s.id ? "bg-[#043561] text-white shadow-xl" : "text-slate-400 hover:text-slate-600")}>
                {s.label}
              </button>
            ))}
          </div>
        </header>

        <div className="mb-12 space-y-4">
          <textarea
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
