          </div>
        </div>

        {result && !result.error && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
             <div className="mb-10 flex flex-col lg:flex-row lg:items-center justify-between gap-8 border-b border-slate-50 pb-8">
              <div className="flex-1">
                <div className="flex gap-2 mb-4">
                  <span className="px-3 py-1 bg-[#043561] text-[#00ff00] text-[8px] font-black uppercase tracking-widest rounded-lg">{result.categoria}</span>
                </div>
                <h3 className="text-4xl md:text-5xl font-black text-[#043561] tracking-tighter uppercase italic leading-none">{result.titulo_projeto}</h3>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-16">
              <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
                <label className="text-[9px] font-black text-[#0081cc] uppercase tracking-widest block mb-4 italic">Meta de Ensino</label>
                <p className="text-slate-500 font-bold text-lg leading-snug italic">"{result.meta_educativa}"</p>
              </div>
              <div className="bg-[#f0f9ff] p-8 rounded-[3rem] border border-blue-100">
                <label className="text-[9px] font-black text-[#043561] uppercase tracking-widest block mb-4 italic">Gancho de Retenção</label>
